#![allow(clippy::unwrap_used)]
use vw_raster::*;
fn image()->DecodedImage {DecodedImage{width:2,height:1,pixels:Pixels::Rgba8(vec![255,0,0,255,0,255,0,73]),icc:Some(standard_srgb_profile().unwrap()),source_asset:vw_model::AssetId::hash(b"display-original"),original_available:true,orientation_applied:1}}
fn options()->DisplayOptions {DisplayOptions{space:DisplaySpace::DisplayP3,assume_untagged_srgb:false,allow_depth_reduction:false,memory_budget_bytes:128*1024*1024,retained_bytes:0}}
fn region()->Region{Region{x:0,y:0,width:2,height:1}}
#[test] fn srgb_to_p3_changes_components_preserves_alpha_and_original(){let source=image();let old=source.clone();let out=display_region(&source,region(),options(),&||false).unwrap();assert_ne!(out.rgba,source.pixels.rgba8());assert_eq!((out.rgba[3],out.rgba[7]),(255,73));assert_eq!(source,old);assert_eq!(out.icc,display_profile(DisplaySpace::DisplayP3).unwrap());assert_eq!(out.source_asset,source.source_asset);}
#[test] fn tagged_same_space_is_identity_with_rounding_bound(){let source=image();let mut o=options();o.space=DisplaySpace::Srgb;let out=display_region(&source,region(),o,&||false).unwrap();for(a,b)in out.rgba.iter().zip(source.pixels.rgba8()){assert!((i16::from(*a)-i16::from(b)).abs()<=1);}assert!(!out.depth_reduced&&!out.assumed_srgb);}
#[test] fn untagged_and_depth_choices_are_independent_explicit_admissions(){let mut source=image();source.icc=None;assert!(matches!(display_region(&source,region(),options(),&||false),Err(RasterError::Unsupported(_))));let mut o=options();o.assume_untagged_srgb=true;source.pixels=Pixels::Rgba16(vec![65535,0,0,65535,0,65535,0,32768]);assert!(matches!(display_region(&source,region(),o,&||false),Err(RasterError::Depth)));o.allow_depth_reduction=true;let out=display_region(&source,region(),o,&||false).unwrap();assert!(out.assumed_srgb&&out.depth_reduced);assert_eq!(out.rgba[7],128);assert_eq!(source.pixels.bit_depth(),16);}
#[test] fn small_budget_refuses_before_semantic_profile_parser(){let mut source=image();let profile=source.icc.as_mut().unwrap();profile[16..20].copy_from_slice(b"CMYK");let mut o=options();o.memory_budget_bytes=1024;assert!(matches!(display_region(&source,region(),o,&||false),Err(RasterError::Memory{..})));}
#[test] fn source_capacity_and_external_retained_bytes_are_charged(){let mut source=image();let Pixels::Rgba8(ref mut p)=source.pixels else{unreachable!()};p.reserve_exact(4*1024*1024);let base=display_peak(&source,region(),options()).unwrap();let mut o=options();o.retained_bytes=base;o.memory_budget_bytes=base;assert!(matches!(display_peak(&source,region(),o),Err(RasterError::Memory{..})));}
#[test] fn cancelled_and_out_of_source_regions_return_no_derivative(){let source=image();assert!(matches!(display_region(&source,region(),options(),&||true),Err(RasterError::Cancelled)));let bad=Region{x:1,y:0,width:2,height:1};assert!(display_region(&source,bad,options(),&||false).is_err());}
#[test] fn unknown_lut_profile_route_is_explicitly_refused(){let mut source=image();let profile=source.icc.as_mut().unwrap();profile[132..136].copy_from_slice(b"A2B0");assert!(matches!(display_region(&source,region(),options(),&||false),Err(RasterError::Unsupported(_))));}
#[test] fn display_crop_has_exact_source_origin_and_deterministic_profile(){let source=image();let r=Region{x:1,y:0,width:1,height:1};let out=display_region(&source,r,options(),&||false).unwrap();assert_eq!(out.region,r);assert_eq!(out.rgba.len(),4);assert_eq!(out.rgba[3],73);assert_eq!(display_profile(DisplaySpace::DisplayP3).unwrap(),display_profile(DisplaySpace::DisplayP3).unwrap());}
#[test] fn unverified_preview_is_never_admitted_as_an_original(){let mut source=image();source.original_available=false;assert!(matches!(display_region(&source,region(),options(),&||false),Err(RasterError::OriginalRequired)));}
#[test] fn late_cancel_discards_the_converted_derivative(){let source=image();let calls=std::cell::Cell::new(0usize);assert!(matches!(display_region(&source,region(),options(),&||{let n=calls.get();calls.set(n+1);n>=2}),Err(RasterError::Cancelled)));assert_eq!(source,image());}
#[test] fn high_depth_tagged_source_remains_exact_after_display_reduction(){let mut source=image();source.pixels=Pixels::Rgba16(vec![65535,512,4096,32768,1234,56789,4321,65535]);let original=source.clone();let mut o=options();o.allow_depth_reduction=true;let out=display_region(&source,region(),o,&||false).unwrap();assert_eq!(source,original);assert_eq!(out.source_bit_depth,16);assert!(out.depth_reduced&&!out.assumed_srgb);assert_eq!((out.rgba[3],out.rgba[7]),(128,255));}
